local function AnimationControl()
	local l0 = 0
	l0 = 0
	while true do
		if moving ~= 0 or s1 ~= 0 then
			if l0 == 0 then
				Show(tracks1)
				Hide(tracks4)
				l0 = l0 + 1
			elseif l0 == 1 then
				Show(tracks2)
				Hide(tracks1)
				l0 = l0 + 1
			elseif l0 == 2 then
				Show(tracks3)
				Hide(tracks2)
				l0 = l0 + 1
			elseif l0 == 3 then
				Show(tracks4)
				Hide(tracks3)
				l0 = 0
				if s1 ~= 0 then
					s1 = s1 - 1
				end
			end
			s2 = s2 + 1
		end
		Sleep(50)
	end
end

local function DamageControl()
	local l0 = 0
	while true do
		l0 = GetUnitValue(COB.HEALTH)
		if l0 < 50 then
			Spring.SpawnCEG("blacksmokesmall", Spring.GetUnitPiecePosDir(unitID, body))  -- damage smoke (SF)
			if l0 < 25 then
				Spring.SpawnCEG("burnblacksmall", Spring.GetUnitPiecePosDir(unitID, turret))  -- damage fire (SF)
			end
