function script.Create()
	moving = 0
	Hide(tracks1)
	Hide(tracks2)
	Hide(tracks3)
	while GetUnitValue(COB.BUILD_PERCENT_LEFT) ~= 0 do
		Sleep(250)
	end
	StartThread(AnimationControl)
	StartThread(DamageControl)
end

function script.StartMoving()
	moving = 1
	s2 = 0
	Spin(wheels1, x_axis, rad(240), rad(45))
	Spin(wheels5, x_axis, rad(240), rad(45))
	Spin(wheels2, x_axis, rad(360), rad(60))
	Spin(wheels3, x_axis, rad(360), rad(60))
